        question: "<div style='color: #1a237e; font-size: 16px; font-weight: bold;'>'રેસનો ઘોડો' પાઠના લેખિકાનું નામ અને તેનો સાહિત્ય પ્રકાર જણાવો.</div>",
        answer: "<div style='background-color: #f5f7fa; padding: 12px; border-left: 4px solid #2196f3; border-radius: 5px; font-size: 15px; color: #333;'><h4 style='color: #0d47a1; margin-top: 0;'>ઉકેલ:</h4>લેખિકાનું નામ <b>વર્ષા અડાલજા</b> છે અને આ પાઠનો સાહિત્ય પ્રકાર <b>નવલિકા (ટૂંકી વાર્તા)</b> છે.<br><br><div style='background-color: #fff3e0; padding: 10px; margin-top: 15px; border-radius: 5px; border-left: 4px solid #ff9800; color: #e65100; font-weight: bold;'>🚀 નિતેશ સરની શોર્ટકટ ટ્રીક: ઘોડો ક્યારે દોડે? જ્યારે 'વર્ષા' (વરસાદ) ન હોય ત્યારે! અને રેસ થોડા સમય માટે જ હોય, એટલે 'ટૂંકી વાર્તા' (નવલિકા). બસ આ રીતે લેખિકા અને પ્રકાર યાદ રાખી લો.</div></div>"
