        year_asked: "[March 2023]",
        question: "<div style='color: #1a237e; font-size: 16px; font-weight: bold;'>કવયિત્રી વારંવાર કોને નમવાની વાત કરે છે?</div>",
        answer: "<div style='background-color: #f5f7fa; padding: 12px; border-left: 4px solid #2196f3; border-radius: 5px; font-size: 15px; color: #333;'><h4 style='color: #0d47a1; margin-top: 0;'>ઉકેલ:</h4>કવયિત્રી <b>શીલવંત (ચારિત્ર્યવાન) સાધુને</b> વારંવાર નમવાની વાત કરે છે, જેના વર્તનમાં ક્યારેય કોઈ ખરાબ પરિવર્તન આવતું નથી.<br><br></div>"
