        answer: "<div style='background-color: #f5f7fa; padding: 12px; border-left: 4px solid #2196f3; border-radius: 5px; font-size: 15px; color: #333;'><h4 style='color: #0d47a1; margin-top: 0;'>ઉકેલ:</h4>૧. <b>શીલવંત</b> = ચારિત્ર્યવાન / સદાચારી<br>૨. <b>પરમારથ</b> = પરમાર્થ / ઈશ્વરભક્તિ / મોક્ષ<br>૩. <b>નિર્મળ</b> = પવિત્ર / શુદ્ધ<br><br></div>"
