        answer: "<div style='background-color: #f5f7fa; padding: 12px; border-left: 4px solid #2196f3; border-radius: 5px; font-size: 15px; color: #333;'><h4 style='color: #0d47a1; margin-top: 0;'>ઉકેલ:</h4>લેખકનું નામ <b>રઘુવીર ચૌધરી</b> છે અને આ પાઠનો સાહિત્ય પ્રકાર <b>એકાંકી (નાટક)</b> છે.<br><br><div style='background-color: #fff3e0; padding: 10px; margin-top: 15px; border-radius: 5px; border-left: 4px solid #ff9800; color: #e65100; font-weight: bold;'>🚀 નિતેશ સરની શોર્ટકટ ટ્રીક: 'ભૂલી ગયા પછી' રઘુવીર યાદ આવ્યા! આ રીતે લેખકનું નામ યાદ રાખો. અને આ પાઠમાં સ્ટેજ પર ભજવી શકાય તેવા ડાયલોગ્સ છે, એટલે તે 'એકાંકી' (એક અંકવાળું નાટક) કહેવાય.</div></div>"
